    private void Start()
    {
        MeasureFunctionExecutionTime();
    }

    private void MeasureFunctionExecutionTime()
    {
        Measure("Unity MonoBehaviour", () => unitySorter.TestSort((int[])numbers.Clone(), numbers.Length));

        Measure("C#", () => Array.Sort((int[])numbers.Clone()));

        Measure("C++", () => TestDLLSort.Sorter.TestSort((int[])numbers.Clone(), numbers.Length));
    }

    private void Measure(string name, Action sortFunction)
    {
        Stopwatch stopwatch = Stopwatch.StartNew();

        sortFunction();

        stopwatch.Stop();

        double elapsedMilliseconds = stopwatch.ElapsedTicks * 1000.0 / Stopwatch.Frequency;

        Debug.Log($"{name}: {elapsedMilliseconds:F6} ms");
    }
}